  void Show(){Window.Show();Window.WindowState=WindowState.Normal;Window.Activate();search.Focus();}
  void Quit(){SearchRuntime.Stop();if(queryCts!=null)queryCts.Cancel();if(translateCts!=null)translateCts.Cancel();if(tray!=null){tray.Visible=false;tray.Dispose();tray=null;}if(hotkey)UnregisterHotKey(hwnd,1);Window.Close();Application.Current.Shutdown();}
  void SetInput(string s){search.Text=s;search.CaretIndex=s.Length;search.Focus();Refresh();}
  public static string Mode(string s){return s.StartsWith("f ",StringComparison.OrdinalIgnoreCase)?"files":s.StartsWith("tr ",StringComparison.OrdinalIgnoreCase)?"translate":s.StartsWith("> ")?"command":"all";}
  async void Refresh(){mode=Mode(search.Text);foreach(var pair in new[]{new[]{"AllButton","all"},new[]{"FileButton","files"},new[]{"TranslateButton","translate"},new[]{"TerminalButton","command"}}){Get<Button>(pair[0]).BorderBrush=new SolidColorBrush(pair[1]==mode?Color.FromRgb(85,214,190):Colors.Transparent);}trPane.Visibility=mode=="translate"?Visibility.Visible:Visibility.Collapsed;cmdPane.Visibility=mode=="command"?Visibility.Visible:Visibility.Collapsed;results.Visibility=mode=="all"||mode=="files"?Visibility.Visible:Visibility.Collapsed;
   if(mode=="translate"){status.Text="Ctrl+Enter 提交翻译 · 仅发送当前输入文本";return;}if(mode=="command"){status.Text="普通权限执行 · 请确认命令与工作目录";return;}
   if(mode=="files"){int request=version;var text=search.Text.Substring(2).Trim();if(queryCts!=null)queryCts.Cancel();queryCts=new CancellationTokenSource();var token=queryCts.Token;results.ItemsSource=null;if(text.Length==0){status.Text="输入文件名或 Everything 搜索语法，例如 ext:pdf 合同";return;}status.Text="正在查询 Everything…首次全盘索引可能需要几分钟";try{var found=await Services.Files(settings,text,token,message=>{if(request==version&&!token.IsCancellationRequested)status.Text=message;});if(request!=version||token.IsCancellationRequested)return;Bind(found);status.Text=found.Count==0?"没有匹配文件。":"显示前 "+found.Count+" 项 · Tab 展开文件操作";}catch(OperationCanceledException){}catch(Exception e){if(request==version)status.Text=e.Message;}return;}
   string q=search.Text.Trim();var web=WebSearch.Match(q);if(web!=null){Bind(new List<Entry>{web});status.Text=web.Target==null?"输入关键词和搜索内容，例如 bd 26年新能源车推荐":"按 Enter 在默认浏览器打开搜索结果";return;}var all=apps.Concat(tools).Concat(settings.Commands.Select(c=>new Entry{Name=c.Name,Detail=c.Directory+"  ·  "+c.Command,Kind="命令",Glyph="\uE756",Target=c.Directory,Command=c.Command,Alias=Services.Initials(c.Name)}));var matched=all.Select(e=>new{Item=e,Rank=Services.Rank(e,q)}).Where(e=>e.Rank>0).OrderByDescending(e=>e.Rank).ThenBy(e=>e.Item.Name).Take(60).Select(e=>e.Item).ToList();if(q.Length==0)matched=tools.Concat(apps.Take(8)).ToList();Bind(matched);status.Text=matched.Count==0?"没有匹配应用。搜索文件请点击“文件”或输入 f 。":"已发现 "+apps.Count+" 个开始菜单应用 · 支持名称和常用汉字首字母";if(!hotkey&&!smoke)status.Text+=" · 快捷键不可用，请使用托盘";
