  void Bind(List<Entry> list){string old=(results.SelectedItem as Entry)==null?null:((Entry)results.SelectedItem).Target;results.ItemsSource=list;results.SelectedItem=list.FirstOrDefault(e=>e.Target==old)??list.FirstOrDefault();}
  async void Keys(object sender,KeyEventArgs e){if(composing||e.Key==Key.ImeProcessed)return;var current=Mode(search.Text);if(e.Key==Key.Escape){if(current!="all")SetInput("");else Window.Hide();e.Handled=true;return;}if(e.Key==Key.Enter){if(current=="translate"){if((Keyboard.Modifiers&ModifierKeys.Control)!=0){await Translate();e.Handled=true;}}else if(current=="command"){if(e.OriginalSource==search){Safe(Run);e.Handled=true;}}else if(e.OriginalSource==search||results.IsKeyboardFocusWithin){Safe(Execute);e.Handled=true;}return;}
   if(results.Visibility==Visibility.Visible&&(e.OriginalSource==search||results.IsKeyboardFocusWithin)){if(e.Key==Key.Down||e.Key==Key.Up){results.SelectedIndex=Math.Max(0,Math.Min(results.Items.Count-1,results.SelectedIndex+(e.Key==Key.Down?1:-1)));if(results.SelectedItem!=null)results.ScrollIntoView(results.SelectedItem);e.Handled=true;}if(e.Key==Key.Tab&&Keyboard.Modifiers==ModifierKeys.None){Actions();e.Handled=true;}}
  }
  void Execute(){var item=results.SelectedItem as Entry;if(item==null)return;if(item.Kind=="网页"&&item.Target==null){status.Text="请在关键词后输入搜索内容。";search.Focus();return;}if(item.Kind=="工具"){switch(item.Target){case "capture":Capture();break;case "translate":SetInput("tr ");break;case "terminal":SetInput("> ");break;case "files":SetInput("f ");break;case "settings":ShowSettings();break;}return;}if(item.Kind=="命令"){working.Text=item.Target;SetInput("> "+item.Command);return;}Services.Open(item.Target);Window.Hide();}
  void Actions(){var item=results.SelectedItem as Entry;if(item==null)return;var menu=new ContextMenu{Background=new SolidColorBrush(Color.FromRgb(34,38,44)),Foreground=Brushes.White};AddMenu(menu,"打开",Execute);if(item.Kind=="文件"||item.Kind=="应用"){AddMenu(menu,"复制路径",()=>Copy(item.Target));AddMenu(menu,"打开所在位置",()=>{if(!File.Exists(item.Target)&&!Directory.Exists(item.Target))throw new IOException("此路径已不存在。");System.Diagnostics.Process.Start("explorer.exe","/select,"+Services.Quote(item.Target));});if(item.Folder){AddMenu(menu,"在此打开终端",()=>{Services.Terminal("",item.Target);Window.Hide();});AddMenu(menu,"在此运行命令",()=>{working.Text=item.Target;SetInput("> ");});}}menu.PlacementTarget=results;menu.Closed+=(s,e)=>search.Focus();menu.IsOpen=true;((MenuItem)menu.Items[0]).Focus();}
  void AddMenu(ContextMenu m,string name,Action a){var i=new MenuItem{Header=name};i.Click+=(s,e)=>Safe(a);m.Items.Add(i);}
  void Copy(string text){if(String.IsNullOrEmpty(text))return;Clipboard.SetText(text);status.Text="已复制到剪贴板。";}
  void Run(){if(Mode(search.Text)!="command")return;string command=search.Text.Substring(2);if(String.IsNullOrWhiteSpace(command)){status.Text="请先输入命令。";return;}Services.Terminal(command,working.Text);Window.Hide();}
  void SaveCommand(){if(Mode(search.Text)!="command"||String.IsNullOrWhiteSpace(search.Text.Substring(2)))return;var input=new TextBox{Text=search.Text.Substring(2),Margin=new Thickness(0,10,0,14)};var dialog=Dialog("收藏命令",440,240);var stack=(StackPanel)((ContentControl)dialog.Tag).Content;stack.Children.Add(new TextBlock{Text="名称（搜索此名称即可再次使用）"});stack.Children.Add(input);var save=Button("保存",()=>{if(String.IsNullOrWhiteSpace(input.Text))return;settings.Commands.Add(new SavedCommand{Name=input.Text.Trim(),Command=search.Text.Substring(2),Directory=working.Text});Store.Save(settings);dialog.Close();status.Text="已收藏命令。";});stack.Children.Add(save);dialog.ShowDialog();}
  async Task Translate(){if(Mode(search.Text)!="translate")return;string text=search.Text.Substring(3).Trim();if(text.Length==0){status.Text="请在 tr 后输入要翻译的文字。";return;}if(translateCts!=null)translateCts.Cancel();var local=new CancellationTokenSource();translateCts=local;int request=version;string target=language;translation.Clear();status.Text="正在翻译…";try{string result=await Services.Translate(settings,text,target,local.Token);if(!local.IsCancellationRequested&&request==version){translation.Text=result;status.Text="翻译完成。";}}catch(OperationCanceledException){if(request==version&&translateCts==local)status.Text="请求已取消或超时，可重试。";}catch(Exception e){if(request==version&&translateCts==local)status.Text=e.Message;}}
  void Capture(){Window.Hide();var delay=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(250)};delay.Tick+=(s,e)=>{delay.Stop();try{var capture=new CaptureWindow();capture.ShowDialog();}catch(Exception ex){Show();status.Text="截图失败："+ex.Message;}};delay.Start();}
